def minimum_added_coins(coins,target):
    coins=sorted(coins);reach=1;index=answer=0
    while reach<=target:
        if index<len(coins) and coins[index]<=reach:
            reach+=coins[index];index+=1
        else:
            reach*=2;answer+=1
    return answer

